/// <summary>
/// N.Freidenberger TASK12586 28.11.2024
/// </summary>
/// <param name = "_callerRecord">_callerRecord</param>
public void new(Common      _callerRecord)
{
    AVADAIReport                avaDAIReport;
    FieldId                     refFieldId; 

    select firstonly avaDAIReport
        where avaDAIReport.AckRefTableName == tableId2Name(_callerRecord.TableId);

    if (_callerRecord.TableId != tableNum(CustQuotationJour))
    {
        refFieldId = fieldName2Id(_callerRecord.TableId,avaDAIReport.AckRefTableFieldName);
    }
    else
    {
        refFieldId = fieldNum(CustQuotationJour,QuotationDocNum);

    }

    select firstonly daiReportExportTable
        where daiReportExporttable.RefNum == _callerRecord.(refFieldId);


}

/// <summary>
/// N.Freidenberger TASK12586 28.11.2024
/// </summary>
public void callReport()
{
    AVADAIReportExportWork                                  daiReportExportWork;
    System.IO.Stream                                        ioStream;

    select firstonly daiReportExportWork
        where daiReportExportWork.ReportExportTable == daiReportExportTable.RecId;

    if (conLen(daiReportExportWork.ReportData) != 0)
    {
        ioStream          = Binary::constructFromContainer(daiReportExportWork.ReportData).getMemoryStream();

        if (ioStream)
        {
            str url = File::SendFileToTempStore(ioStream, daiReportExportTable.ReportFileName, classstr (FileUploadTemporaryStorageStrategy));

            new Browser().navigate(url, true);
        }
    }
    else
    {
        warning("@NDX:NXANoReportInArchive");
    }
}
